import type { Column, Typed, TableName, FullSchema, Schema } from '../db'

/**
 * Represents any valid type within a Flow definition.
 * It can be a primitive `Column` (from the database layer),
 * a nested `FlowObjectType`, or a `FlowArrayType`.
 */
export type FlowValueType = Column | FlowObjectType | FlowArrayType

/**
 * Defines the structure for an object within a Flow.
 * This type can be recursive, allowing nested object structures.
 * @template F - A record defining the fields of the object, where keys are field names
 *               and values are `FlowValueType`.
 */

export interface FlowObjectType<F extends Record<string, FlowValueType> = Record<string, FlowValueType>> {
    /** The actual field definitions for this object. */
    fields: F
    /** A user-friendly label for this object type. */
    label: string
    /** Indicates if this object instance is required. */
    mandatory?: boolean
    /** Pairs of any supported dictionary attributes (sys_schema_attribute) */
    attributes?: Record<string, string | number | boolean>
}

type FlowArrayElementType = Column | FlowObjectType<Record<string, Column | FlowObjectType>>

// Helper type to ensure FlowArrayType is never allowed as an element type with a user-friendly error
type ValidFlowArrayElementType<T> = T extends FlowArrayType
    ? { __error: 'FlowArray cannot contain another FlowArray as an element. Use Column or FlowObject instead.' }
    : T

/**
 * Defines the structure for an array within a Flow.
 */
export interface FlowArrayType<F extends FlowArrayElementType = FlowArrayElementType> {
    /** The `FlowValueType` for elements within the array. */
    elementType: ValidFlowArrayElementType<F>
    /** A user-friendly label for this array type. */
    label: string
    /** Indicates if this array instance is required. */
    mandatory?: boolean
    /** A hint or help text for this array. */
    hint?: string
    /** Maximum number of rows allowed in this array. */
    maxRows?: number
}

/**
 * Factory function to create a `FlowObjectType` instance.
 * @template F - A record defining the fields of the object.
 * @template C - The specific config type, preserving literal types like mandatory: true
 * @returns A `FlowObjectType` configured with the provided parameters.
 * @param config
 */
export function FlowObject<const F extends Record<string, FlowValueType>, const C extends FlowObjectType<F>>(
    config: C & FlowObjectType<F>
): C {
    return config
}

/**
 * Factory function to create a `FlowArrayType` instance.
 * @template F - The element type for the array.
 * @template C - The specific config type, preserving literal types like mandatory: true
 * @returns A `FlowArrayType` configured with the provided parameters.
 * @param config
 */
export function FlowArray<const F extends FlowArrayElementType, const C extends FlowArrayType<F>>(
    config: C & FlowArrayType<F> & { elementType: ValidFlowArrayElementType<F>; childName: string }
): C {
    return config
}

/**
 * Infers the corresponding TypeScript/JavaScript object type from a `FlowObjectType`.
 * This utility recursively unwraps nested `FlowObjectType`s and resolves `Typed<R>`
 * (e.g., database columns) to their underlying type `R`.
 * For ReferenceColumns, applies dotwalk support with TableAwareRecordWithFallback.
 *
 * @template T - The `FlowObjectType` from which to infer the TypeScript type.
 *                 It must extend `FlowObjectType`.
 */
type InferFlowObject<T extends FlowObjectType> = {
    [K in keyof T['fields'] as K extends string ? K : never]: T['fields'][K] extends FlowObjectType
        ? InferFlowObject<T['fields'][K]> // Recursively infer for nested FlowObjects
        : T['fields'][K] extends FlowArrayType
          ? InferFlowArray<T['fields'][K]> // Infer for nested FlowArrays
          : ExtractRefTable<T['fields'][K]> extends never
            ? T['fields'][K] extends Typed<infer R>
                ? R
                : unknown
            : TableAwareRecordWithFallback<ExtractRefTable<T['fields'][K]>> // Reference column with dotwalk
}

type InferFlowArray<T extends FlowArrayType> = T['elementType'] extends FlowObjectType
    ? InferFlowObject<T['elementType']>[] // Array of inferred objects
    : T['elementType'] extends Typed<infer R>
      ? R[] // Array of the base type
      : unknown[]

/**
 * A utility type to infer the TypeScript/JavaScript type from any `FlowValueType`.
 * - If `C` is a `Typed<T>` (e.g., a database column), it resolves to the base type `T`.
 * - If `C` is a `FlowObjectType`, it uses `InferFlowObject` to determine its structure.
 * - Otherwise, it resolves to `unknown`.
 *
 * @template C - The `FlowValueType` (Column, FlowObjectType, or FlowArrayType) to infer.
 */
type TypeOfWithFlowObject<C> =
    C extends Typed<infer T>
        ? T
        : C extends FlowObjectType
          ? InferFlowObject<C>
          : C extends FlowArrayType
            ? InferFlowArray<C>
            : unknown

/**
 * Transforms a Flow schema definition (a record of `FlowValueType`s)
 * into its corresponding TypeScript/JavaScript type representation.
 * Each property in the resulting type will have its type inferred using `TypeOfWithFlowObject`.
 *
 * @template I - The input schema definition, expected to be a record where keys are string
 *               identifiers and values are `FlowValueType`.
 */
export type FlowSchemaType<I extends Record<string, FlowValueType>> = {
    [C in keyof I as C extends string ? C : never]: TypeOfWithFlowObject<I[C]>
}

/**
 * Helper type to check if a field has mandatory: true
 */
type IsMandatory<T> = T extends { mandatory: true } ? true : false

/**
 * Helper to determine if a field should be included (visible and not hidden).
 * Returns false if the field has attributes.visible='false' or attributes.visible_in_fd='false'
 */
type IsVisibleField<T> = T extends { attributes: infer A }
    ? A extends { visible: 'false' | false } | { visible_in_fd: 'false' | false }
        ? false
        : true
    : true

/**
 * Helper to get the typed value for a field from the schema
 */
type GetFieldType<T extends Record<string, FlowValueType>, K extends keyof T> = K extends keyof FlowSchemaType<T>
    ? FlowSchemaType<T>[K]
    : never

/**
 * Transform inputs/outputs to have mandatory fields required and optional fields as optional.
 * Fields with visible='false' are completely excluded from IntelliSense/content assist.
 * This type:
 * 1. Filters out hidden fields (visible='false')
 * 2. Makes visible mandatory fields required
 * 3. Makes visible optional fields optional
 *
 * Note: Strict type checking (preventing excess properties) is enforced at the function level
 * using the Exact type in Action, Trigger, and Subflow function signatures.
 */
export type FlowIOType<T extends Record<string, FlowValueType>> = {
    // Required fields: visible AND mandatory
    [K in keyof T as IsVisibleField<T[K]> extends true
        ? IsMandatory<T[K]> extends true
            ? K
            : never
        : never]: GetFieldType<T, K>
} & {
    // Optional fields: visible AND NOT mandatory
    [K in keyof T as IsVisibleField<T[K]> extends true
        ? IsMandatory<T[K]> extends true
            ? never
            : K
        : never]?: GetFieldType<T, K>
}

// ============================================================================
// Dotwalk Support Types - Reusable types for reference column traversal
// ============================================================================

/**
 * Depth counter for recursive types - uses tuple indexing to decrement.
 * Prev[3] = 2, Prev[2] = 1, Prev[1] = 0, Prev[0] = never (stops recursion)
 */
export type DotwalkDepth = [never, 0, 1, 2, 3, 4]

/**
 * Extract the referenced table name from a column if it's a ReferenceColumn.
 * Returns the referenceTable property if present and valid, otherwise never.
 */
export type ExtractRefTable<C> = C extends { referenceTable: infer RT } ? (RT extends TableName ? RT : never) : never

/**
 * Check if a table has a defined schema in the workspace.
 * Returns true if FullSchema<T> has at least one key, false if schema is empty/undefined.
 */
export type HasDefinedSchema<T extends TableName> = string extends keyof Schema<T> ? false : true

/**
 * Resolve a column type with recursive dot-walking for reference columns.
 * For ReferenceColumns: returns the referenced table's TableAwareRecord (recursive)
 * For other columns: returns TypeOf<C>
 * Depth parameter prevents infinite recursion for self-referencing tables.
 * When referenced table schema is not defined, returns unknown to restrict arbitrary property access.
 */
export type ResolveColumnType<C, D extends number> = [D] extends [never]
    ? C extends Typed<infer T>
        ? T
        : unknown // Depth exhausted, fall back to base type
    : ExtractRefTable<C> extends never
      ? C extends Typed<infer T>
          ? T
          : unknown // Not a reference column, use base type
      : HasDefinedSchema<ExtractRefTable<C>> extends true
        ? TableAwareRecordRecursive<ExtractRefTable<C>, DotwalkDepth[D]> // Schema defined, use strict typing
        : Record<string, unknown> // Schema not defined, allow single-level property access with unknown values

/**
 * Helper type to remove index signatures from a type.
 * This is needed because Tables extends Record<string, ...> which adds an index signature.
 */
type KnownKeys<T> = {
    [K in keyof T as string extends K ? never : number extends K ? never : K]: T[K]
}

/**
 * Recursive table-aware record type with dot-walking support for reference columns.
 * Maps each field to either its TypeOf (for non-references) or the referenced table's schema (for references).
 * Depth parameter limits recursion (default 3 levels: current.field.ref.ref).
 *
 * Note: Uses KnownKeys to remove index signature and allow dot notation access on defined fields.
 */
export type TableAwareRecordRecursive<T extends TableName, D extends number = 3> = {
    [K in keyof KnownKeys<FullSchema<T>>]: ResolveColumnType<KnownKeys<FullSchema<T>>[K], D>
}

/**
 * Public type alias - table-aware record with recursive reference resolution (3 levels deep).
 * Enables dot-walking like: current.sys_scope.owner.manager
 */
export type TableAwareRecord<T extends TableName> = TableAwareRecordRecursive<T, 3>

/**
 * Table-aware record with fallback for undefined schemas.
 * - If table schema IS defined: use TableAwareRecord<T> for type-safe field access
 * - If table schema is NOT defined: allow property access (values are untyped)
 */
export type TableAwareRecordWithFallback<T extends TableName> =
    HasDefinedSchema<T> extends true ? TableAwareRecord<T> : Record<string, unknown>

/**
 * Resolve an output field type with dotwalk support for reference columns.
 * If the column references a table, provides dotwalk access to that table's fields.
 * Otherwise falls back to the base type with arbitrary property access for datapill references.
 */
export type OutputFieldWithDotwalk<C extends Column> =
    ExtractRefTable<C> extends never
        ? // Not a reference column, use base type with arbitrary access for datapills
          (C extends Typed<infer T> ? T : unknown) & Record<string, FlowValueType>
        : // Reference column, use table-aware record with dotwalk
          TableAwareRecordWithFallback<ExtractRefTable<C>>

/**
 * Transform output schema to TypeScript types with dotwalk support for reference columns.
 * Each output field that is a reference column will have dotwalk access to the referenced table's fields.
 * Note: FlowObject and FlowArray do not support ReferenceColumn, so they use standard type inference.
 * IMPORTANT: Check FlowObjectType and FlowArrayType FIRST before Column to avoid structural type matching issues.
 */
export type OutputsWithDotwalk<O extends Record<string, FlowValueType>> = {
    [K in keyof O]: O[K] extends FlowObjectType
        ? InferFlowObject<O[K]>
        : O[K] extends FlowArrayType
          ? InferFlowArray<O[K]>
          : O[K] extends Column
            ? OutputFieldWithDotwalk<O[K]>
            : TypeOfWithFlowObject<O[K]>
}

// ============================================================================
// Dependent Output Types - For outputs that depend on input values (e.g., table_name)
// ============================================================================

/**
 * Check if a column has a 'dependent' property indicating it depends on an input field.
 */
export type HasDependentField<C> = C extends { dependent: string } ? true : false

/**
 * Extract the dependent field name from a column (e.g., 'table_name').
 */
export type ExtractDependentField<C> = C extends { dependent: infer D } ? (D extends string ? D : never) : never

/**
 * Resolve an output field type based on the input table.
 * If the column has a `dependent` property pointing to a table input, and we know the table,
 * provide table-aware typing with dotwalk support.
 *
 * @template C - The output column type
 * @template TTable - The table name from the input (inferred at call site)
 */
export type ResolveOutputWithTable<C, TTable extends TableName> = C extends { dependent: string }
    ? // Has dependent field - check if base type is array (e.g., RecordsColumn)
      C extends Typed<infer T>
        ? T extends Array<unknown>
            ? // Array type (RecordsColumn) - return array of table-aware records
              TableAwareRecordWithFallback<TTable>[]
            : // Non-array type (DocumentIdColumn) - return single table-aware record
              TableAwareRecordWithFallback<TTable>
        : TableAwareRecordWithFallback<TTable>
    : // No dependent field, use standard output field resolution
      C extends Column
      ? OutputFieldWithDotwalk<C>
      : unknown

/**
 * Transform outputs with dependent field resolution based on input table.
 * This type takes the outputs schema AND the input table to provide correct typing.
 * Uses KnownKeys to remove index signature from the constraint.
 *
 * @template O - The outputs schema
 * @template TTable - The table name from input (e.g., 'incident', 'pa_dashboards')
 */
export type OutputsWithDependentTable<O extends Record<string, FlowValueType>, TTable extends TableName> = {
    [K in keyof KnownKeys<O>]: KnownKeys<O>[K] extends FlowObjectType
        ? InferFlowObject<KnownKeys<O>[K]>
        : KnownKeys<O>[K] extends FlowArrayType
          ? InferFlowArray<KnownKeys<O>[K]>
          : KnownKeys<O>[K] extends Column
            ? ResolveOutputWithTable<KnownKeys<O>[K], TTable>
            : TypeOfWithFlowObject<KnownKeys<O>[K]>
}
